INSERT INTO @sinPasos SELECT t.Id FROM TiposDocumento t WHERE NOT EXISTS (SELECT 1 FROM PasosPlantilla p WHERE p.TipoDocumentoId = t.Id);
INSERT INTO PasosPlantilla (TipoDocumentoId, Orden, Clase, Nombre) SELECT t.Id, 1, N'Revision', N'Revisión' FROM TiposDocumento t WHERE t.Codigo = N'P' AND t.Id IN (SELECT TipoId FROM @sinPasos);
INSERT INTO PasosPlantilla (TipoDocumentoId, Orden, Clase, Nombre) SELECT t.Id, 2, N'Aprobacion', N'Aprobación' FROM TiposDocumento t WHERE t.Codigo = N'P' AND t.Id IN (SELECT TipoId FROM @sinPasos);
